INSERT INTO dbo.business_rule (rule_id, rule_code, rule_name, rule_category, bureau_code, lob_scope, record_type_scope, state_scope, element_code, expression_json, severity, message, business_description, eff_date, exp_date, status, created_by, created_at, approved_by, approved_at, supersedes_id, notes) VALUES (15, N'VR001', N'Policy number required', N'VALIDATION', N'ISO', N'*', N'*', N'*', N'POLICY_NUMBER', N'{"op": "required"}', N'ERROR', N'Policy number is missing', N'Every premium and loss record must carry the policy number.', N'2020-01-01', N'9999-12-31', N'APPROVED', N'seed: ISO layout import', N'2026-10-12 16:17:56', N'Demo SME', N'2026-10-12T12:17:56', NULL, NULL);
INSERT INTO dbo.business_rule (rule_id, rule_code, rule_name, rule_category, bureau_code, lob_scope, record_type_scope, state_scope, element_code, expression_json, severity, message, business_description, eff_date, exp_date, status, created_by, created_at, approved_by, approved_at, supersedes_id, notes) VALUES (16, N'VR002', N'Expiration after effective', N'VALIDATION', N'ISO', N'*', N'PREMIUM', N'*', N'POLICY_EXP_DATE', N'{"op": "compare", "left": "POLICY_EXP_DATE", "cmp": ">", "right": "POLICY_EFF_DATE"}', N'ERROR', N'Policy expiration date must be after the effective date', N'Policy term must be positive.', N'2020-01-01', N'9999-12-31', N'APPROVED', N'seed: ISO layout import', N'2026-10-12 16:17:56', N'Demo SME', N'2026-10-12T12:17:56', NULL, NULL);
INSERT INTO dbo.business_rule (rule_id, rule_code, rule_name, rule_category, bureau_code, lob_scope, record_type_scope, state_scope, element_code, expression_json, severity, message, business_description, eff_date, exp_date, status, created_by, created_at, approved_by, approved_at, supersedes_id, notes) VALUES (17, N'VR003', N'Risk ZIP is 5 digits', N'VALIDATION', N'ISO', N'*', N'PREMIUM', N'*', N'RISK_ZIP', N'{"op": "regex", "pattern": "^\\d{5}$"}', N'ERROR', N'Risk ZIP must be 5 digits', N'Garaging / risk ZIP must be a valid 5-digit ZIP.', N'2020-01-01', N'9999-12-31', N'APPROVED', N'seed: ISO layout import', N'2026-10-12 16:17:56', N'Demo SME', N'2026-10-12T12:17:56', NULL, NULL);
INSERT INTO dbo.business_rule (rule_id, rule_code, rule_name, rule_category, bureau_code, lob_scope, record_type_scope, state_scope, element_code, expression_json, severity, message, business_description, eff_date, exp_date, status, created_by, created_at, approved_by, approved_at, supersedes_id, notes) VALUES (18, N'VR004', N'Loss within policy period', N'VALIDATION', N'ISO', N'*', N'LOSS', N'*', N'LOSS_DATE', N'{"op": "between", "field": "LOSS_DATE", "from": "POLICY_EFF_DATE", "to": "POLICY_EXP_DATE"}', N'ERROR', N'Date of loss is outside the policy period', N'A loss must occur while the policy is in force.', N'2020-01-01', N'9999-12-31', N'APPROVED', N'seed: ISO layout import', N'2026-10-12 16:17:56', N'Demo SME', N'2026-10-12T12:17:56', NULL, NULL);
INSERT INTO dbo.business_rule (rule_id, rule_code, rule_name, rule_category, bureau_code, lob_scope, record_type_scope, state_scope, element_code, expression_json, severity, message, business_description, eff_date, exp_date, status, created_by, created_at, approved_by, approved_at, supersedes_id, notes) VALUES (19, N'VR005', N'Loss not after accounting date', N'VALIDATION', N'ISO', N'*', N'LOSS', N'*', N'LOSS_DATE', N'{"op": "compare", "left": "LOSS_DATE", "cmp": "<=", "right": "ACCT_DATE"}', N'ERROR', N'Date of loss is after the accounting date', N'A claim cannot be booked before it occurs.', N'2020-01-01', N'9999-12-31', N'APPROVED', N'seed: ISO layout import', N'2026-10-12 16:17:56', N'Demo SME', N'2026-10-12T12:17:56', NULL, NULL);
INSERT INTO dbo.business_rule (rule_id, rule_code, rule_name, rule_category, bureau_code, lob_scope, record_type_scope, state_scope, element_code, expression_json, severity, message, business_description, eff_date, exp_date, status, created_by, created_at, approved_by, approved_at, supersedes_id, notes) VALUES (20, N'VR006', N'Closed claims carry no reserve', N'VALIDATION', N'ISO', N'*', N'LOSS', N'*', N'OS_RESERVE', N'{"op": "when", "if": {"field": "CLAIM_STATUS", "in": ["CL", "FP"]}, "then": {"op": "compare", "left": "OS_RESERVE", "cmp": "==", "value": 0}}', N'ERROR', N'Closed / final-payment claim still shows an outstanding reserve', N'When the claim is closed or final payment, the outstanding reserve must be zero.', N'2020-01-01', N'9999-12-31', N'APPROVED', N'seed: ISO layout import', N'2026-10-12 16:17:56', N'Demo SME', N'2026-10-12T12:17:56', NULL, NULL);
INSERT INTO dbo.business_rule (rule_id, rule_code, rule_name, rule_category, bureau_code, lob_scope, record_type_scope, state_scope, element_code, expression_json, severity, message, business_description, eff_date, exp_date, status, created_by, created_at, approved_by, approved_at, supersedes_id, notes) VALUES (21, N'VR007', N'Negative paid loss is a recovery', N'VALIDATION', N'ISO', N'*', N'LOSS', N'*', N'PAID_LOSS', N'{"op": "compare", "left": "PAID_LOSS", "cmp": ">=", "value": 0}', N'WARNING', N'Negative paid loss - confirm salvage / subrogation recovery', N'Flag recoveries for SME review.', N'2020-01-01', N'9999-12-31', N'APPROVED', N'seed: ISO layout import', N'2026-10-12 16:17:56', N'Demo SME', N'2026-10-12T12:17:56', NULL, NULL);
INSERT INTO dbo.business_rule (rule_id, rule_code, rule_name, rule_category, bureau_code, lob_scope, record_type_scope, state_scope, element_code, expression_json, severity, message, business_description, eff_date, exp_date, status, created_by, created_at, approved_by, approved_at, supersedes_id, notes) VALUES (22, N'VR008', N'Zero premium transaction', N'VALIDATION', N'ISO', N'*', N'PREMIUM', N'*', N'WRITTEN_PREMIUM', N'{"op": "compare", "left": "WRITTEN_PREMIUM", "cmp": "!=", "value": 0}', N'WARNING', N'Written premium is zero', N'Zero-premium transactions are usually not reportable; SME confirms.', N'2020-01-01', N'9999-12-31', N'APPROVED', N'seed: ISO layout import', N'2026-10-12 16:17:56', N'Demo SME', N'2026-10-12T12:17:56', NULL, NULL);
INSERT INTO dbo.business_rule (rule_id, rule_code, rule_name, rule_category, bureau_code, lob_scope, record_type_scope, state_scope, element_code, expression_json, severity, message, business_description, eff_date, exp_date, status, created_by, created_at, approved_by, approved_at, supersedes_id, notes) VALUES (23, N'VR009', N'Cancellation returns premium', N'VALIDATION', N'ISO', N'*', N'PREMIUM', N'*', N'WRITTEN_PREMIUM', N'{"op": "when", "if": {"field": "TRANSACTION_TYPE", "in": ["CN"]}, "then": {"op": "compare", "left": "WRITTEN_PREMIUM", "cmp": "<=", "value": 0}}', N'ERROR', N'Cancellation must carry zero or negative premium', N'Cancellations return premium.', N'2020-01-01', N'9999-12-31', N'APPROVED', N'seed: ISO layout import', N'2026-10-12 16:17:56', N'Demo SME', N'2026-10-12T12:17:56', NULL, NULL);
INSERT INTO dbo.business_rule (rule_id, rule_code, rule_name, rule_category, bureau_code, lob_scope, record_type_scope, state_scope, element_code, expression_json, severity, message, business_description, eff_date, exp_date, status, created_by, created_at, approved_by, approved_at, supersedes_id, notes) VALUES (24, N'VR010', N'Accounting date in run period', N'VALIDATION', N'ISO', N'*', N'*', N'*', N'ACCT_DATE', N'{"op": "between", "field": "ACCT_DATE", "from": "$batch.period_start", "to": "$batch.period_end"}', N'ERROR', N'Accounting date is outside the reporting period', N'Only transactions booked in the period are reported.', N'2020-01-01', N'9999-12-31', N'APPROVED', N'seed: ISO layout import', N'2026-10-12 16:17:56', N'Demo SME', N'2026-10-12T12:17:56', NULL, NULL);
INSERT INTO dbo.business_rule (rule_id, rule_code, rule_name, rule_category, bureau_code, lob_scope, record_type_scope, state_scope, element_code, expression_json, severity, message, business_description, eff_date, exp_date, status, created_by, created_at, approved_by, approved_at, supersedes_id, notes) VALUES (25, N'VR011', N'Catastrophe code for wind / hail', N'VALIDATION', N'ISO', N'CP,HO,BP,BR,IM', N'LOSS', N'*', N'CAT_CODE', N'{"op": "when", "if": {"field": "CAUSE_OF_LOSS", "in": ["WIND", "HAIL"]}, "then": {"op": "required"}}', N'WARNING', N'Wind / hail loss without a catastrophe code', N'Wind and hail losses are usually tied to a PCS event.', N'2020-01-01', N'9999-12-31', N'APPROVED', N'seed: ISO layout import', N'2026-10-12 16:17:56', N'Demo SME', N'2026-10-12T12:17:56', NULL, NULL);
